vline.setFillOpacity(0);
const dA = new Dot({ point: ax.c2p(m, fA(m)), color: BLUE });
const dB = new Dot({ point: ax.c2p(m, fB(m)), color: ORANGE });
dA.addUpdater(() => dA.moveTo(ax.c2p(m, fA(m))));
dB.addUpdater(() => dB.moveTo(ax.c2p(m, fB(m))));
scene.add(vline, dA, dB);

let readout = null;
function updateReadout() {
  if (readout) scene.remove(readout);
  const a = fA(m), b = fB(m);
  let verdict = 'Same cost!';
