  else if (b < a - 1e-9) verdict = 'Plan B is cheaper';
  readout = new Text({
    text: m.toFixed(0) + ' min:  A = $' + a.toFixed(2) + '   B = $' + b.toFixed(2) + '   -> ' + verdict,
    color: WHITE,
    fontSize: 22
  });
  readout.moveTo([-0.8, -3.6, 0]);
  scene.add(readout);
}
